#!/usr/bin/env node
/**
 * Wires up the three DEX Scout background jobs on cron-job.org via their REST API.
 *
 * This script never asks for or stores your cron-job.org login — it only uses an API key that
 * cron-job.org itself lets you carry credentials for, generated by you in your own account, and it
 * never leaves your machine (it isn't sent anywhere except cron-job.org's API).
 *
 * Setup (you do this part — see VERCEL.md):
 *   1. Create a free account at https://cron-job.org and verify your email.
 *   2. Console -> Settings -> API key -> generate one, copy it.
 *   3. Run this script with three env vars set:
 *        CRONJOB_ORG_API_KEY = the key from step 2
 *        APP_URL             = https://<your-app>.vercel.app  (no trailing slash)
 *        CRON_SECRET         = the same value as the CRON_SECRET env var on Vercel
 *
 * Example:
 *   CRONJOB_ORG_API_KEY=xxx APP_URL=https://dex-scout.vercel.app CRON_SECRET=yyy node scripts/setup-cronjob-org.mjs
 *
 * Safe to re-run: it looks for jobs it already created (by title) and updates them instead of
 * creating duplicates.
 */

const API = "https://api.cron-job.org";
const apiKey = process.env.CRONJOB_ORG_API_KEY;
const appUrl = (process.env.APP_URL || "").replace(/\/+$/, "");
const cronSecret = process.env.CRON_SECRET;

if (!apiKey || !appUrl || !cronSecret) {
  console.error("Missing required env vars. Need CRONJOB_ORG_API_KEY, APP_URL and CRON_SECRET.");
  console.error("See the comment at the top of this file for how to get each one.");
  process.exit(1);
}
if (!/^https:\/\//.test(appUrl)) {
  console.error(`APP_URL must start with https:// (got "${appUrl}")`);
  process.exit(1);
}

const EVERY = [-1]; // cron-job.org's "every hour/day/month/weekday" sentinel
const everyNMinutes = (n) => Array.from({ length: Math.ceil(60 / n) }, (_, i) => i * n).filter((m) => m < 60);

const JOBS = [
  { title: "dexscout-scan", path: "/api/cron/scan", minutes: everyNMinutes(2) },
  { title: "dexscout-monitor", path: "/api/cron/monitor", minutes: EVERY },
  { title: "dexscout-execute", path: "/api/cron/execute", minutes: EVERY },
];

async function api(method, path, body) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: { Authorization: `Bearer ${apiKey}`, "content-type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  const json = text ? JSON.parse(text) : {};
  if (!res.ok) throw new Error(`${method} ${path} -> HTTP ${res.status}: ${text.slice(0, 300)}`);
  return json;
}

function jobPayload(j) {
  return {
    enabled: true,
    title: j.title,
    saveResponses: true,
    url: `${appUrl}${j.path}`,
    requestMethod: 0, // GET
    requestTimeout: 90,
    notification: { onFailure: true, onFailureCount: 1, onSuccess: true, onDisable: true },
    extendedData: { headers: { Authorization: `Bearer ${cronSecret}` } },
    schedule: { timezone: "UTC", expiresAt: 0, hours: EVERY, mdays: EVERY, minutes: j.minutes, months: EVERY, wdays: EVERY },
  };
}

async function main() {
  console.log(`Wiring up cron-job.org jobs for ${appUrl} ...`);
  const { jobs: existing } = await api("GET", "/jobs");
  for (const j of JOBS) {
    const payload = jobPayload(j);
    const found = existing.find((e) => e.title === j.title);
    if (found) {
      await api("PATCH", `/jobs/${found.jobId}`, { job: payload });
      console.log(`updated  ${j.title}  (jobId ${found.jobId})  -> ${payload.url}`);
    } else {
      const { jobId } = await api("PUT", "/jobs", { job: payload });
      console.log(`created  ${j.title}  (jobId ${jobId})  -> ${payload.url}`);
    }
  }
  console.log("\nDone. Verify in the cron-job.org console, or watch the Dashboard's");
  console.log('"Background workers" card in the app once a couple of runs have happened.');
}

main().catch((err) => {
  console.error("Failed:", err.message);
  process.exit(1);
});
